with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'), ch as (
insert into public.academy_chapters(course_id,title,description,sort_order,published)
select id,'الأرصاد الجوية العلوية وديناميكية الغلاف الجوي','تركيب الغلاف الجوي والضغط والرصد العلوي والتحليل السينوبتيكي والرياح العليا.',12,false from c
on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'بنية الغلاف الجوي',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الضغط والارتفاعات الجوية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الرصد الجوي العلوي',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u4 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'قراءة الخرائط السينوبتيكية',4,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u5 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'ديناميكية الرياح العلوية',5,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('upper-atmosphere-structure','تركيب الغلاف الجوي والطبقات الرأسية','بنية الطبقات الحرارية وتغير الحرارة والضغط والكثافة مع الارتفاع','{"blocks":[{"type":"text","text":"الغلاف الجوي مزيج من الغازات تحكم الجاذبية ارتباطه بالأرض. وتتغير خصائصه رأسياً بسبب اختلاف التسخين والإشعاع والتركيب."},{"type":"text","text":"تقسم طبقاته حرارياً إلى التروبوسفير والستراتوسفير والميزوسفير والثرموسفير، وتفصل بينها مناطق انتقالية."},{"type":"text","text":"تقع معظم الظواهر الجوية في التروبوسفير، حيث تنخفض الحرارة غالباً مع الارتفاع، مع إمكان ظهور انقلابات حرارية."},{"type":"text","text":"يتغير ارتفاع التروبوبوز مع خط العرض والفصل والحالة الجوية؛ ويكون أعلى عادة في المناطق المدارية وأخفض قرب القطبين."},{"type":"text","text":"تحتوي الستراتوسفير على معظم الأوزون، وترتفع الحرارة في جزء منها بسبب امتصاص الأشعة فوق البنفسجية."},{"type":"text","text":"تنخفض الحرارة في الميزوسفير ثم ترتفع في الثرموسفير نتيجة امتصاص الإشعاع الشمسي عالي الطاقة."},{"type":"text","text":"ينخفض الضغط والكثافة مع الارتفاع لأن كتلة الهواء فوق المستوى تتناقص، ويكون الانخفاض غير خطي."},{"type":"text","text":"تتغير الطبقة الحدية بتأثير تسخين السطح وتبريده والاحتكاك والتبخر، ويختلف سمكها خلال اليوم."},{"type":"text","text":"الانقلاب الحراري طبقة ترتفع فيها الحرارة مع الارتفاع، وقد تحد من الخلط الرأسي قرب السطح."},{"type":"text","text":"تختلف الطبقات الرأسية مكانياً وزمانياً؛ فلا يصح اعتماد ارتفاع ثابت للتروبوبوز في جميع المناطق."},{"type":"text","text":"مثال: عند مقارنة سبر جوي مداري وآخر قطبي، افحص ارتفاع التروبوبوز وملف الحرارة بدلاً من افتراض حد موحد."},{"type":"callout","text":"خلاصة: فهم التركيب الرأسي ضروري لتفسير السحب والاستقرار والرياح وانتقال الطاقة والمواد."}]}',500,50,'["فهم الطبقات الجوية","تفسير تغير الحرارة والضغط","تمييز الطبقة الحدية والانقلاب الحراري"]','بنية الغلاف الجوي'),
('pressure-geopotential-height','الضغط الجوي والارتفاع الجيوپوتنسيالي','الضغط والاتزان الهيدروستاتيكي والتمييز بين الارتفاع الهندسي والجيوپوتنسيالي','{"blocks":[{"type":"text","text":"الضغط الجوي قوة عمودية لكل وحدة مساحة ناتجة عن وزن عمود الهواء، ويقاس بالهيكتوباسكال أو الباسكال."},{"type":"text","text":"ينخفض الضغط مع الارتفاع لأن وزن الهواء الموجود فوق النقطة يقل."},{"type":"text","text":"يعبر الاتزان الهيدروستاتيكي عن توازن تدرج الضغط الرأسي مع وزن الهواء، ويكتب dp/dz = -ρg."},{"type":"text","text":"تربط العلاقة الهيدروستاتيكية تغير الضغط الرأسي بكثافة الهواء وتسارع الجاذبية."},{"type":"text","text":"يمكن اشتقاق علاقة الارتفاع بين مستويين ضغطيين باستخدام قانون الغاز المثالي ومتوسط درجة الحرارة الافتراضية للطبقة."},{"type":"text","text":"الارتفاع الهندسي مسافة رأسية عن مرجع هندسي، أما الارتفاع الجيوپوتنسيالي فيأخذ تغير الجاذبية في الحسبان."},{"type":"text","text":"تستخدم خرائط الطقس مستويات ضغط معيارية مثل 850 و700 و500 و300 hPa."},{"type":"text","text":"لا يقع مستوى الضغط نفسه على ارتفاع ثابت؛ إذ يتغير ارتفاعه مع بنية الحرارة والضغط."},{"type":"text","text":"تصل خطوط تساوي الارتفاع بين نقاط لها الارتفاع الجيوپوتنسيالي نفسه على سطح ضغط محدد."},{"type":"text","text":"تقارب خطوط الارتفاع يدل على تدرج أفقي أكبر، ويرتبط غالباً برياح جيوستروفية أقوى مع ثبات العوامل الأخرى."},{"type":"text","text":"مثال: انخفاض ارتفاع 500 hPa نسبياً قد يشير إلى أخدود علوي، ويجب فحص الحرارة والرياح والتطور الزمني."},{"type":"callout","text":"خلاصة: الضغط والارتفاع الجيوپوتنسيالي أساس تحليل البنية الرأسية والحركة واسعة النطاق."}]}',510,50,'["شرح الضغط ووحداته","تفسير الاتزان الهيدروستاتيكي","تمييز أنواع الارتفاع"]','الضغط والارتفاعات الجوية'),
('radiosonde-upper-air-observations','البالونات الجوية والراديوسوند وقياسات الطبقات العليا','الرصد الرأسي للحرارة والرطوبة والضغط والرياح ومخططات السبر','{"blocks":[{"type":"text","text":"توفر قياسات الطبقات العليا وصفاً رأسياً للغلاف الجوي لا تستطيع المحطات السطحية توفيره."},{"type":"text","text":"يحمل بالون الأرصاد جهاز راديوسوند إلى طبقات الجو العليا، ويرتفع مع انخفاض الضغط المحيط."},{"type":"text","text":"تضم المنظومة حساسات للحرارة والرطوبة والضغط أو الارتفاع، ونظام تحديد موقع ومرسلاً لاسلكياً."},{"type":"text","text":"تقاس المتغيرات على فترات متتابعة، وتستخدم بيانات الموقع والزمن لاشتقاق الرياح الأفقية."},{"type":"text","text":"يمثل ملف السبر تغير الحرارة والرطوبة مع الضغط أو الارتفاع، ويساعد في تحليل الاستقرار والسحب."},{"type":"text","text":"يعرض مخطط Skew-T log-P درجة الحرارة ودرجة الندى ومسارات الحزم الهوائية على محور ضغط لوغاريتمي."},{"type":"text","text":"من المؤشرات المشتقة مستوى التكاثف الحملي LCL ومستوى الحمل الحر LFC ومستوى الاتزان EL."},{"type":"text","text":"تستخدم CAPE وCIN لتقييم طاقة الحمل ومقاومة بدء الحركة الصاعدة، ولا يكفي أي منهما منفرداً للتنبؤ."},{"type":"text","text":"يمثل مسار البالون انجرافه مع الرياح أثناء الصعود، وليس عموداً رأسياً فوق نقطة الإطلاق."},{"type":"text","text":"تتأثر القياسات بتأخر استجابة الحساس والإشعاع والبرودة وفقد الاتصال وجودة تحديد الموقع."},{"type":"text","text":"مثال: تقييم عدم الاستقرار يتطلب قراءة الحرارة والرطوبة والرياح وعمق الطبقة الرطبة مع المؤشرات المشتقة."},{"type":"callout","text":"خلاصة: الراديوسوند أداة أساسية لفهم البنية الرأسية ويدمج مع الأقمار والرادار والخرائط."}]}',520,50,'["شرح منظومة الراديوسوند","قراءة ملف السبر","تفسير المؤشرات المشتقة"]','الرصد الجوي العلوي'),
('synoptic-pressure-height-charts','تحليل خرائط الضغط والارتفاعات عند المستويات القياسية','قراءة خرائط الضغط السطحي والمستويات العليا وتحديد الأنظمة واسعة النطاق','{"blocks":[{"type":"text","text":"تعرض الخريطة السينوبتيكية حالة الغلاف الجوي على مساحة واسعة وفي وقت محدد."},{"type":"text","text":"توضح خرائط الضغط السطحي خطوط تساوي الضغط وتساعد على تحديد المنخفضات والمرتفعات."},{"type":"text","text":"المنخفض منطقة ضغط أقل نسبياً من محيطها، والمرتفع منطقة ضغط أعلى نسبياً."},{"type":"text","text":"تنشأ قوة تدرج الضغط من الاختلاف الأفقي في الضغط، وتتوازن جزئياً مع قوة كوريوليس في الحركة واسعة النطاق."},{"type":"text","text":"تعرض خرائط 850 و700 و500 و300 hPa ارتفاع السطح الذي يساوي الضغط المحدد."},{"type":"text","text":"يستخدم مستوى 850 hPa لدراسة الحرارة والرطوبة والرياح في الطبقات السفلى، وقد يقع تحت سطح الأرض فوق الجبال."},{"type":"text","text":"يساعد مستوى 700 hPa على تحليل الرطوبة والحركة الرأسية في الطبقات المتوسطة."},{"type":"text","text":"يستخدم مستوى 500 hPa لدراسة الأخاديد والنتوءات والدوامات العلوية."},{"type":"text","text":"يساعد مستوى 300 hPa على متابعة الرياح القوية والتيارات النفاثة في الطبقات العليا."},{"type":"text","text":"يمتد الأخدود نحو ارتفاعات أقل نسبياً، بينما يمتد النتوء نحو ارتفاعات أعلى."},{"type":"text","text":"مثال: تحليل أخدود علوي يتطلب ربط موقعه بالرطوبة والرفع والمنخفض السطحي والتيار النفاث."},{"type":"callout","text":"خلاصة: قراءة عدة مستويات معاً تقدم تفسيراً أشمل من خريطة منفردة."}]}',530,50,'["قراءة خرائط الضغط","تفسير مستويات الضغط","تحديد الأخاديد والنتوءات"]','قراءة الخرائط السينوبتيكية'),
('upper-winds-jet-streams-vorticity','الرياح العلوية والتيارات النفاثة والدوامات الجوية','الرياح الجيوستروفية والحرارية والتيارات النفاثة والقص والدوامية','{"blocks":[{"type":"text","text":"تتأثر الرياح العلوية بتدرج الضغط الأفقي وقوة كوريوليس، ويقل تأثير الاحتكاك السطحي المباشر مع الارتفاع."},{"type":"text","text":"تنشأ الرياح الجيوستروفية تقريبياً من توازن تدرج الضغط مع قوة كوريوليس، وتسير موازية لخطوط تساوي الارتفاع في الحالة المثالية."},{"type":"text","text":"تصف علاقة الرياح الحرارية تغير الرياح الجيوستروفية مع الارتفاع بسبب التدرج الأفقي لدرجة الحرارة."},{"type":"text","text":"التيار النفاث نطاق من الرياح القوية في الطبقات العليا، غالباً قرب التروبوبوز."},{"type":"text","text":"يرتبط التيار النفاث القطبي بالتباين الحراري بين العروض، بينما يرتبط شبه المداري بالدوران العام."},{"type":"text","text":"القص هو تغير متجه الرياح مكانياً، رأسياً أو أفقياً، ويؤثر في تنظيم السحب والعواصف."},{"type":"text","text":"الدوامية النسبية تقيس الدوران المحلي للهواء بالنسبة إلى الأرض."},{"type":"text","text":"الدوامية المطلقة تجمع الدوامية النسبية والدوامية الكوكبية المرتبطة بدوران الأرض."},{"type":"text","text":"قد يرتبط التباعد العلوي بحركة صاعدة تعوض فقد الكتلة من العمود الهوائي، وفق بنية النظام ثلاثية الأبعاد."},{"type":"text","text":"موجات روسبي اضطرابات واسعة النطاق في الدوران الجوي تؤثر في تعرج الرياح الغربية ومسارات الأنظمة."},{"type":"text","text":"مثال: عند اقتراب أخدود علوي افحص التيار النفاث والقص والدوامية والتباعد مع النظام السطحي."},{"type":"callout","text":"خلاصة: مفاهيم الرياح العلوية تفسر تطور الأنظمة واسعة النطاق وتدعم التنبؤ."}]}',540,50,'["شرح الرياح الجيوستروفية","التعرف إلى التيارات النفاثة","تفسير القص والدوامية"]','ديناميكية الرياح العلوية'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'بنية الغلاف الجوي' then u1.id when 'الضغط والارتفاعات الجوية' then u2.id when 'الرصد الجوي العلوي' then u3.id when 'قراءة الخرائط السينوبتيكية' then u4.id else u5.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'الأرصاد الجوية العلوية وديناميكية الغلاف الجوي',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4 cross join u5
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;